import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Los íconos de la app, de línea y con las puntas redondeadas como los SF Symbols del iPhone: Material Symbols Rounded
 * (Apache 2.0), peso 500, rellenos donde iOS usa el `.fill`. Los de Material Icons, rellenos y más gruesos, hacían ver a
 * Android de otra familia (Mati, 15-oct). `material-icons` no está en el proyecto (y no se agregan dependencias): van los
 * trazados en vectores propios. La pesa, Revisión y Progreso están dibujados como los de iOS. Se pintan con el color que
 * les ponga `Icon(tint = …)`.
 */
object Iconos {
    private fun icono(nombre: String, vararg trazados: String): ImageVector =
        ImageVector.Builder(name = nombre, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
            .apply { for (t in trazados) addPath(pathData = addPathNodes(t), fill = SolidColor(Color.Black)) }
            .build()

    /** Material Symbols: grilla de 960 con el origen abajo (`viewBox="0 -960 960 960"`), por eso el grupo corrido. */
    private fun simbolo(nombre: String, trazado: String): ImageVector =
        ImageVector.Builder(name = nombre, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
            .addGroup(translationY = 960f)
            .addPath(pathData = addPathNodes(trazado), fill = SolidColor(Color.Black))
            .clearGroup()
            .build()

    /** Un rectángulo redondeado como trazado (para la pesa). */
    private fun rect(x: Float, y: Float, w: Float, h: Float, r: Float): String =
        "M${x + r},${y}H${x + w - r}A$r,$r 0 0 1 ${x + w},${y + r}V${y + h - r}A$r,$r 0 0 1 ${x + w - r},${y + h}" +
            "H${x + r}A$r,$r 0 0 1 $x,${y + h - r}V${y + r}A$r,$r 0 0 1 ${x + r},${y}Z"

    /** Entreno: la pesa de costado, discos afuera y barra al medio. */
    val Pesa: ImageVector by lazy {
        icono(
            "Pesa",
            rect(1f, 8f, 3f, 8f, 1.5f),
            rect(4.75f, 5f, 3.25f, 14f, 1.6f),
            rect(8f, 10.6f, 8f, 2.8f, 0.6f),
            rect(16f, 5f, 3.25f, 14f, 1.6f),
            rect(20f, 8f, 3f, 8f, 1.5f),
        )
    }

